package jobs

import (
	"errors"
	"strings"
	"testing"
)

func TestSafeCause(t *testing.T) {
	tests := []struct {
		name     string
		err      error
		want     string   // exact output when non-empty
		contains []string // substrings that must be present
		absent   []string // substrings that must be gone
	}{
		{name: "nil error", err: nil, want: ""},
		{name: "plain text unchanged", err: errors.New("Repository not found."), want: "Repository not found."},
		{name: "text with a colon and no URL unchanged", err: errors.New("fatal: could not read Username: terminal prompts disabled"),
			want: "fatal: could not read Username: terminal prompts disabled"},
		{
			name:     "user and password",
			err:      errors.New("fatal: unable to access 'REDACTED': 403"),
			contains: []string{"https://gitlab.example/g/app.git/", "403"},
			absent:   []string{"glpat-abc", "oauth2:", "@gitlab"},
		},
		{name: "user only", err: errors.New("https://user@host/x"), want: "https://host/x"},
		{name: "ssh scheme", err: errors.New("ssh://git@host:22/x"), want: "ssh://host:22/x"},
		{name: "scp form has no secret", err: errors.New("git@github.com:o/r.git"), want: "git@github.com:o/r.git"},
		{
			name:     "private_token query value",
			err:      errors.New("GET https://h/api/v4/groups?private_token=REDACTED&page=2: 401"),
			contains: []string{"page=2", "401"},
			absent:   []string{"abc"},
		},
		{
			name:     "token query value",
			err:      errors.New("GET https://h/x?token=abc123&page=2: 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "access_token query value",
			err:      errors.New("GET https://h/x?page=2&access_token=REDACTED 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "query key is case-insensitive",
			err:      errors.New("GET https://h/x?PRIVATE_TOKEN=REDACTED&page=2: 401"),
			contains: []string{"page=2"},
			absent:   []string{"abc123"},
		},
		{
			name:     "several URLs in one message",
			err:      errors.New("clone REDACTED then REDACTED failed"),
			contains: []string{"one.example/x.git", "two.example/y.git", "failed"},
			absent:   []string{"s1", "s2", "s3", "a:", "b:"},
		},
		{
			name:     "wrapped error",
			err:      errors.Join(errors.New("walk"), errors.New("REDACTED")),
			contains: []string{"walk", "https://h/x"},
			absent:   []string{"REDACTED"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := SafeCause(tt.err)
			if tt.want != "" || tt.err == nil || len(tt.contains) == 0 {
				if got != tt.want {
					t.Fatalf("SafeCause = %q, want %q", got, tt.want)
				}
			}
			for _, s := range tt.contains {
				if !strings.Contains(got, s) {
					t.Errorf("SafeCause = %q, want it to contain %q", got, s)
				}
			}
			for _, s := range tt.absent {
				if strings.Contains(got, s) {
					t.Errorf("SafeCause = %q, must not contain %q", got, s)
				}
			}
		})
	}
}
package explorer

import (
	"bytes"
	"errors"
	"log"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/jobs"
)

const leakyCloneErr = "fatal: unable to access 'REDACTED': 403"

// D97: a git error can carry a URL with credentials; the Detail is shown on
// screen and in screenshots.
func TestACloneFailureDetailCarriesNoSecret(t *testing.T) {
	for _, kind := range []cloneEventKind{cloneEnded, cloneWalkFailed} {
		tr := CloneEventMsg{event: cloneEvent{kind: kind, path: "alpha/api", err: errors.New(leakyCloneErr)}}.Transition()
		if tr.State != jobs.ItemFailed {
			t.Fatalf("kind %v: state = %v, want failed", kind, tr.State)
		}
		for _, secret := range []string{"glpat-SECRET", "oauth2:"} {
			if strings.Contains(tr.Detail, secret) {
				t.Errorf("kind %v: detail %q leaks %q", kind, tr.Detail, secret)
			}
		}
		if !strings.Contains(tr.Detail, "gitlab.example/alpha/api.git") || !strings.Contains(tr.Detail, "403") {
			t.Errorf("kind %v: detail %q lost the useful part of the cause", kind, tr.Detail)
		}
	}
}

func TestAWalkFailureKeepsItsDiscoveryPrefix(t *testing.T) {
	tr := CloneEventMsg{event: cloneEvent{kind: cloneWalkFailed, path: "alpha/sub", err: errors.New("403")}}.Transition()
	if tr.Detail != "discovery: 403" {
		t.Errorf("detail = %q, want %q", tr.Detail, "discovery: 403")
	}
}

// H2: a clone skipped because the directory exists says why.
func TestASkippedCloneSaysItIsAlreadyOnDisk(t *testing.T) {
	tr := CloneEventMsg{event: cloneEvent{kind: cloneEnded, path: "alpha/api", skipped: true}}.Transition()
	if tr.State != jobs.ItemSkipped {
		t.Errorf("state = %v, want skipped", tr.State)
	}
	if tr.Detail != "already on disk" {
		t.Errorf("detail = %q, want %q", tr.Detail, "already on disk")
	}
}

// The log is the other place the raw error went.
func TestTheCloneLogCarriesNoSecret(t *testing.T) {
	var buf bytes.Buffer
	prev, flags := log.Writer(), log.Flags()
	log.SetOutput(&buf)
	t.Cleanup(func() { log.SetOutput(prev); log.SetFlags(flags) })

	h := cloning(t)
	h.emit(
		CloneEventMsg{event: cloneEvent{kind: cloneEnded, path: "alpha/api", err: errors.New(leakyCloneErr)}},
		CloneEventMsg{event: cloneEvent{kind: cloneWalkFailed, path: "alpha/sub", err: errors.New(leakyCloneErr)}},
	)

	if buf.Len() == 0 {
		t.Fatal("nothing was logged for a failed clone")
	}
	if strings.Contains(buf.String(), "glpat-SECRET") {
		t.Errorf("log leaks the token: %s", buf.String())
	}
}
